/// <summary>
/// PricingAttribute of table <c>InventTable</c> field PrimaryVendorId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTable, PrimaryVendorId))]
internal class GUPPricingAttributeInventTablePrimaryVendorId extends GUPPricingAttributeInventTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, PrimaryVendorId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTable inventTable;
    VendTable   vendTable;

    while select PrimaryVendorId from inventTable
        join AccountNum from vendTable
        group by inventTable.PrimaryVendorId
        where InventTable.PrimaryVendorId == VendTable.AccountNum
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(inventTable.PrimaryVendorId, vendTable.vendorName());
        ret.add(valueObject);
    }
    return ret;
}
